<script>
 import { computeProbabilityLesson } from '@/lib/formula-lessons/probability-primitives.mjs';
 export let lesson; export let spec;
 let p0=spec.probabilities[0],p1=spec.probabilities[1]; $: p2=Math.max(.01,1-Number(p0)-Number(p1)); $: total=Number(p0)+Number(p1)+p2; $: probabilities=[Number(p0)/total,Number(p1)/total,p2/total]; $: r=computeProbabilityLesson({values:spec.values,probabilities,joint:spec.joint,conditionedColumn:spec.conditionedColumn}); const f=(v,d=4)=>Number(v).toFixed(d);
</script>
<div class="grid" data-probability-primitives-lesson data-focus={lesson.focus}><section class="panel"><p class="eyebrow">Expectation and variance from one PMF</p><h6>E[X]={f(r.mean)} · Var(X)={f(r.variance)} · σ={f(r.std)}</h6>{#each spec.values as value,i}<div class="prob"><span>X={value}</span><i style={`width:${probabilities[i]*100}%`}></i><strong>{f(probabilities[i])}</strong></div>{/each}<label>raw p(X={spec.values[0]}) <output>{f(p0,2)}</output><input bind:value={p0} type="range" min="0.05" max="0.8" step="0.01"/></label><label>raw p(X={spec.values[1]}) <output>{f(p1,2)}</output><input bind:value={p1} type="range" min="0.05" max="0.8" step="0.01"/></label></section><section class="panel"><p class="eyebrow">Conditional probability from joint table</p><h6>P(X|Y=y)</h6>{#each r.conditional as p,i}<div class="prob"><span>x{i}</span><i style={`width:${p*100}%`}></i><strong>{f(p)}</strong></div>{/each}<div class="check">Σ conditional={f(r.conditionalSum,8)}. Conditional expectation uses this normalized conditional law rather than the marginal.</div></section></div>
<style>.grid{display:grid;grid-template-columns:1fr 1fr;gap:.8rem}.panel{border:1px solid var(--color-border);border-radius:1rem;background:var(--color-background);padding:1rem}.eyebrow{margin:0;font-size:.66rem;font-weight:900;text-transform:uppercase;letter-spacing:.1em;color:var(--color-muted-foreground)}h6{margin:.25rem 0 .7rem}.prob{display:grid;grid-template-columns:4rem 1fr 4rem;gap:.45rem;align-items:center;margin:.4rem 0;font-size:.72rem}.prob i{height:.75rem;border-radius:99px;background:var(--color-primary)}.panel label{display:grid;grid-template-columns:1fr auto;gap:.2rem;margin-top:.55rem;font-size:.72rem;font-weight:800}.panel input{grid-column:1/-1;min-height:30px}.check{margin-top:.8rem;border-radius:.7rem;background:var(--color-muted);padding:.7rem;font-size:.72rem;line-height:1.55}@media(max-width:760px){.grid{grid-template-columns:1fr}}</style>
